from pathlib import Path

def write(path: str, content: str) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')

def replace_once(path: str, old: str, new: str) -> None:
    target = Path(path)
    text = target.read_text(encoding='utf-8')
    if old not in text:
        raise SystemExit(f'Pattern not found in {path}: {old[:160]!r}')
    target.write_text(text.replace(old, new, 1), encoding='utf-8')

write('apps/api/src/traceless_api/db/work_management.py', '"""Tenant-scoped enterprise work-management persistence."""\n\nfrom __future__ import annotations\n\nfrom datetime import datetime\nfrom typing import Any\nfrom uuid import UUID, uuid4\n\nfrom sqlalchemy import (\n    JSON,\n    Boolean,\n    CheckConstraint,\n    ForeignKey,\n    Index,\n    Integer,\n    String,\n    Text,\n    UniqueConstraint,\n    Uuid,\n)\nfrom sqlalchemy.orm import Mapped, mapped_column\n\nfrom traceless_api.db.base import Base\nfrom traceless_api.db.models import UTCDateTime, utc_now\n\n\nclass WorkManagementConnectorRow(Base):\n    __tablename__ = "work_management_connectors"\n    __table_args__ = (\n        UniqueConstraint(\n            "organization_id",\n            "name",\n            name="uq_work_management_connector_org_name",\n        ),\n        Index(\n            "ix_work_management_connector_org_provider",\n            "organization_id",\n            "provider",\n        ),\n        CheckConstraint(\n            "provider IN (\'jira\', \'servicenow\', \'azure_devops\')",\n            name="ck_work_management_connector_provider",\n        ),\n    )\n\n    id: Mapped[UUID] = mapped_column(Uuid, primary_key=True, default=uuid4)\n    organization_id: Mapped[UUID] = mapped_column(\n        Uuid,\n        ForeignKey("organizations.id", ondelete="CASCADE"),\n        nullable=False,\n    )\n    name: Mapped[str] = mapped_column(String(120), nullable=False)\n    provider: Mapped[str] = mapped_column(String(32), nullable=False)\n    base_url: Mapped[str] = mapped_column(String(1_000), nullable=False)\n    project_key: Mapped[str] = mapped_column(String(160), nullable=False)\n    credential_reference: Mapped[str] = mapped_column(String(160), nullable=False)\n    enabled: Mapped[bool] = mapped_column(Boolean, default=True, nullable=False)\n    settings: Mapped[dict[str, Any]] = mapped_column(JSON, default=dict, nullable=False)\n    created_by: Mapped[str] = mapped_column(String(160), nullable=False)\n    updated_by: Mapped[str] = mapped_column(String(160), nullable=False)\n    created_at: Mapped[datetime] = mapped_column(UTCDateTime(), default=utc_now)\n    updated_at: Mapped[datetime] = mapped_column(\n        UTCDateTime(),\n        default=utc_now,\n        onupdate=utc_now,\n    )\n\n\nclass RiskTreatmentRow(Base):\n    __tablename__ = "risk_treatments"\n    __table_args__ = (\n        UniqueConstraint("risk_id", name="uq_risk_treatment_risk"),\n        Index("ix_risk_treatment_org_due", "organization_id", "due_at"),\n        Index("ix_risk_treatment_system_status", "system_id", "status"),\n        CheckConstraint(\n            "strategy IN (\'mitigate\', \'accept\', \'transfer\', \'avoid\', \'monitor\')",\n            name="ck_risk_treatment_strategy",\n        ),\n        CheckConstraint(\n            "status IN (\'planned\', \'in_progress\', \'blocked\', \'completed\', "\n            "\'accepted\', \'cancelled\')",\n            name="ck_risk_treatment_status",\n        ),\n        CheckConstraint(\n            "priority IN (\'low\', \'medium\', \'high\', \'critical\')",\n            name="ck_risk_treatment_priority",\n        ),\n        CheckConstraint("version >= 1", name="ck_risk_treatment_version"),\n        CheckConstraint(\n            "strategy <> \'accept\' OR acceptance_expires_at IS NOT NULL",\n            name="ck_risk_treatment_acceptance_expiry",\n        ),\n        CheckConstraint(\n            "status <> \'accepted\' OR strategy = \'accept\'",\n            name="ck_risk_treatment_accepted_strategy",\n        ),\n    )\n\n    id: Mapped[UUID] = mapped_column(Uuid, primary_key=True, default=uuid4)\n    organization_id: Mapped[UUID] = mapped_column(\n        Uuid,\n        ForeignKey("organizations.id", ondelete="CASCADE"),\n        nullable=False,\n    )\n    system_id: Mapped[UUID] = mapped_column(\n        Uuid,\n        ForeignKey("systems_operational.id", ondelete="CASCADE"),\n        nullable=False,\n    )\n    risk_id: Mapped[UUID] = mapped_column(\n        Uuid,\n        ForeignKey("risks_operational.id", ondelete="CASCADE"),\n        nullable=False,\n    )\n    strategy: Mapped[str] = mapped_column(String(20), nullable=False)\n    status: Mapped[str] = mapped_column(String(24), nullable=False)\n    owner: Mapped[str] = mapped_column(String(160), nullable=False)\n    priority: Mapped[str] = mapped_column(String(20), nullable=False)\n    due_at: Mapped[datetime | None] = mapped_column(UTCDateTime())\n    acceptance_expires_at: Mapped[datetime | None] = mapped_column(UTCDateTime())\n    rationale: Mapped[str] = mapped_column(Text, default="", nullable=False)\n    compensating_controls: Mapped[list[str]] = mapped_column(\n        JSON,\n        default=list,\n        nullable=False,\n    )\n    created_by: Mapped[str] = mapped_column(String(160), nullable=False)\n    updated_by: Mapped[str] = mapped_column(String(160), nullable=False)\n    version: Mapped[int] = mapped_column(Integer, default=1, nullable=False)\n    created_at: Mapped[datetime] = mapped_column(UTCDateTime(), default=utc_now)\n    updated_at: Mapped[datetime] = mapped_column(\n        UTCDateTime(),\n        default=utc_now,\n        onupdate=utc_now,\n    )\n\n\nclass ExternalWorkItemRow(Base):\n    __tablename__ = "external_work_items"\n    __table_args__ = (\n        UniqueConstraint(\n            "connector_id",\n            "risk_id",\n            name="uq_external_work_item_connector_risk",\n        ),\n        UniqueConstraint(\n            "organization_id",\n            "idempotency_key",\n            name="uq_external_work_item_org_idempotency",\n        ),\n        Index("ix_external_work_item_system_status", "system_id", "status"),\n        Index("ix_external_work_item_connector", "connector_id"),\n        CheckConstraint(\n            "status IN (\'pending\', \'open\', \'in_progress\', \'resolved\', "\n            "\'closed\', \'failed\')",\n            name="ck_external_work_item_status",\n        ),\n        CheckConstraint(\n            "length(payload_sha256) = 64",\n            name="ck_external_work_item_payload_hash",\n        ),\n    )\n\n    id: Mapped[UUID] = mapped_column(Uuid, primary_key=True, default=uuid4)\n    organization_id: Mapped[UUID] = mapped_column(\n        Uuid,\n        ForeignKey("organizations.id", ondelete="CASCADE"),\n        nullable=False,\n    )\n    system_id: Mapped[UUID] = mapped_column(\n        Uuid,\n        ForeignKey("systems_operational.id", ondelete="CASCADE"),\n        nullable=False,\n    )\n    risk_id: Mapped[UUID] = mapped_column(\n        Uuid,\n        ForeignKey("risks_operational.id", ondelete="CASCADE"),\n        nullable=False,\n    )\n    treatment_id: Mapped[UUID] = mapped_column(\n        Uuid,\n        ForeignKey("risk_treatments.id", ondelete="RESTRICT"),\n        nullable=False,\n    )\n    connector_id: Mapped[UUID] = mapped_column(\n        Uuid,\n        ForeignKey("work_management_connectors.id", ondelete="RESTRICT"),\n        nullable=False,\n    )\n    provider: Mapped[str] = mapped_column(String(32), nullable=False)\n    idempotency_key: Mapped[str] = mapped_column(String(160), nullable=False)\n    title: Mapped[str] = mapped_column(String(500), nullable=False)\n    status: Mapped[str] = mapped_column(String(24), default="pending", nullable=False)\n    external_id: Mapped[str | None] = mapped_column(String(200))\n    external_url: Mapped[str | None] = mapped_column(String(2_000))\n    payload_sha256: Mapped[str] = mapped_column(String(64), nullable=False)\n    request_payload: Mapped[dict[str, Any]] = mapped_column(JSON, nullable=False)\n    response_metadata: Mapped[dict[str, Any]] = mapped_column(\n        JSON,\n        default=dict,\n        nullable=False,\n    )\n    last_error_code: Mapped[str | None] = mapped_column(String(120))\n    last_error_message: Mapped[str | None] = mapped_column(Text)\n    last_synced_at: Mapped[datetime | None] = mapped_column(UTCDateTime())\n    created_by: Mapped[str] = mapped_column(String(160), nullable=False)\n    created_at: Mapped[datetime] = mapped_column(UTCDateTime(), default=utc_now)\n    updated_at: Mapped[datetime] = mapped_column(\n        UTCDateTime(),\n        default=utc_now,\n        onupdate=utc_now,\n    )\n')
write('apps/api/src/traceless_api/models/work_management.py', '"""HTTP contracts for risk treatment and enterprise work-item integrations."""\n\nfrom __future__ import annotations\n\nimport json\nimport re\nfrom collections.abc import Mapping\nfrom datetime import datetime\nfrom typing import Any, Literal\nfrom urllib.parse import urlsplit\nfrom uuid import UUID\n\nfrom pydantic import AwareDatetime, Field, computed_field, field_validator, model_validator\n\nfrom traceless_api.models.common import StrictModel\n\nWorkManagementProvider = Literal["jira", "servicenow", "azure_devops"]\nRiskTreatmentStrategy = Literal["mitigate", "accept", "transfer", "avoid", "monitor"]\nRiskTreatmentStatus = Literal[\n    "planned",\n    "in_progress",\n    "blocked",\n    "completed",\n    "accepted",\n    "cancelled",\n]\nWorkItemStatus = Literal["pending", "open", "in_progress", "resolved", "closed", "failed"]\nPriority = Literal["low", "medium", "high", "critical"]\n\n_PROVIDER_SETTINGS = {\n    "jira": frozenset({"issue_type"}),\n    "servicenow": frozenset({"table", "assignment_group"}),\n    "azure_devops": frozenset({"work_item_type"}),\n}\n_SENSITIVE_SETTING_KEYS = frozenset(\n    {\n        "accesskey",\n        "apikey",\n        "authorization",\n        "clientsecret",\n        "credential",\n        "credentials",\n        "password",\n        "privatekey",\n        "secret",\n        "token",\n    }\n)\n_MAX_SETTING_NODES = 256\n\n\ndef _canonical_https_base_url(value: str) -> str:\n    parsed = urlsplit(value.strip())\n    try:\n        port = parsed.port\n    except ValueError as error:\n        raise ValueError("base_url contains an invalid port") from error\n    host = parsed.hostname.rstrip(".").casefold() if parsed.hostname else ""\n    if (\n        parsed.scheme.casefold() != "https"\n        or not host\n        or parsed.username is not None\n        or parsed.password is not None\n        or parsed.query\n        or parsed.fragment\n    ):\n        raise ValueError(\n            "base_url must be a credential-free HTTPS URL without query or fragment"\n        )\n    path = parsed.path.rstrip("/")\n    rendered_host = f"[{host}]" if ":" in host else host\n    rendered_port = f":{port}" if port not in {None, 443} else ""\n    return f"https://{rendered_host}{rendered_port}{path}"\n\n\ndef _sensitive_setting_paths(value: Any) -> tuple[str, ...]:\n    pending: list[tuple[str, Any]] = [("$", value)]\n    found: list[str] = []\n    visited = 0\n    while pending:\n        path, current = pending.pop()\n        visited += 1\n        if visited > _MAX_SETTING_NODES:\n            raise ValueError("connector settings are too complex")\n        if isinstance(current, Mapping):\n            for key, nested in current.items():\n                key_text = str(key)\n                normalized = re.sub(r"[^a-z0-9]", "", key_text.casefold())\n                child = f"{path}.{key_text}"\n                if normalized in _SENSITIVE_SETTING_KEYS:\n                    found.append(child)\n                pending.append((child, nested))\n        elif isinstance(current, list):\n            pending.extend((f"{path}[{index}]", item) for index, item in enumerate(current))\n    return tuple(sorted(found))\n\n\nclass WorkManagementConnectorCreate(StrictModel):\n    name: str = Field(min_length=2, max_length=120)\n    provider: WorkManagementProvider\n    base_url: str = Field(min_length=8, max_length=1_000)\n    project_key: str = Field(min_length=1, max_length=160)\n    credential_reference: str = Field(\n        min_length=3,\n        max_length=160,\n        pattern=r"^[A-Za-z0-9][A-Za-z0-9._/-]*$",\n    )\n    enabled: bool = True\n    settings: dict[str, Any] = Field(default_factory=dict)\n\n    @field_validator("base_url")\n    @classmethod\n    def base_url_is_https(cls, value: str) -> str:\n        return _canonical_https_base_url(value)\n\n    @model_validator(mode="after")\n    def settings_are_safe_and_provider_specific(self) -> "WorkManagementConnectorCreate":\n        encoded = json.dumps(self.settings, separators=(",", ":"), ensure_ascii=False)\n        if len(encoded.encode()) > 32_000:\n            raise ValueError("connector settings exceed the 32 KB normalized limit")\n        sensitive = _sensitive_setting_paths(self.settings)\n        if sensitive:\n            raise ValueError(\n                "connector settings cannot contain secrets; use credential_reference "\n                f"({\', \'.join(sensitive)})"\n            )\n        unknown = set(self.settings) - _PROVIDER_SETTINGS[self.provider]\n        if unknown:\n            raise ValueError(\n                f"unsupported {self.provider} connector settings: {sorted(unknown)}"\n            )\n        for key, value in self.settings.items():\n            if not isinstance(value, str) or not value.strip() or len(value) > 160:\n                raise ValueError(f"connector setting {key!r} must be a bounded string")\n        if self.provider == "servicenow":\n            table = str(self.settings.get("table") or "task")\n            if re.fullmatch(r"[A-Za-z][A-Za-z0-9_]*", table) is None:\n                raise ValueError("ServiceNow table must be alphanumeric or underscores")\n        return self\n\n\nclass WorkManagementConnectorUpdate(WorkManagementConnectorCreate):\n    pass\n\n\nclass WorkManagementConnectorView(StrictModel):\n    id: UUID\n    organization_id: UUID\n    name: str\n    provider: WorkManagementProvider\n    base_url: str\n    project_key: str\n    credential_reference: str\n    enabled: bool\n    settings: dict[str, Any]\n    created_by: str\n    updated_by: str\n    created_at: AwareDatetime\n    updated_at: AwareDatetime\n\n\nclass RiskTreatmentUpsert(StrictModel):\n    strategy: RiskTreatmentStrategy = "mitigate"\n    status: RiskTreatmentStatus = "planned"\n    owner: str = Field(min_length=2, max_length=160)\n    priority: Priority\n    due_at: AwareDatetime | None = None\n    acceptance_expires_at: AwareDatetime | None = None\n    rationale: str = Field(default="", max_length=10_000)\n    compensating_controls: list[str] = Field(default_factory=list, max_length=100)\n    expected_version: int | None = Field(default=None, ge=1)\n\n    @field_validator("compensating_controls")\n    @classmethod\n    def controls_are_unique_and_bounded(cls, values: list[str]) -> list[str]:\n        normalized = [value.strip() for value in values if value.strip()]\n        if any(len(value) > 500 for value in normalized):\n            raise ValueError("compensating controls may not exceed 500 characters")\n        if len(normalized) != len(set(normalized)):\n            raise ValueError("compensating controls must be unique")\n        return normalized\n\n    @model_validator(mode="after")\n    def acceptance_is_time_limited(self) -> "RiskTreatmentUpsert":\n        if self.strategy == "accept":\n            if self.acceptance_expires_at is None:\n                raise ValueError("accepted risk requires acceptance_expires_at")\n            if len(self.rationale.strip()) < 10:\n                raise ValueError("accepted risk requires a documented rationale")\n            if self.acceptance_expires_at <= datetime.now(\n                self.acceptance_expires_at.tzinfo\n            ):\n                raise ValueError("accepted risk expiry must be in the future")\n        elif self.status == "accepted":\n            raise ValueError("accepted status requires the accept strategy")\n        return self\n\n\nclass RiskTreatmentView(StrictModel):\n    id: UUID\n    organization_id: UUID\n    system_id: UUID\n    risk_id: UUID\n    strategy: RiskTreatmentStrategy\n    status: RiskTreatmentStatus\n    owner: str\n    priority: Priority\n    due_at: AwareDatetime | None\n    acceptance_expires_at: AwareDatetime | None\n    rationale: str\n    compensating_controls: list[str]\n    created_by: str\n    updated_by: str\n    version: int\n    created_at: AwareDatetime\n    updated_at: AwareDatetime\n\n    @computed_field\n    @property\n    def overdue(self) -> bool:\n        return bool(\n            self.due_at is not None\n            and self.status not in {"completed", "accepted", "cancelled"}\n            and self.due_at < datetime.now(self.due_at.tzinfo)\n        )\n\n\nclass ExternalWorkItemCreate(StrictModel):\n    connector_id: UUID\n    idempotency_key: str = Field(\n        min_length=8,\n        max_length=160,\n        pattern=r"^[A-Za-z0-9][A-Za-z0-9._:-]*$",\n    )\n    title: str | None = Field(default=None, min_length=2, max_length=500)\n    description: str | None = Field(default=None, min_length=2, max_length=20_000)\n\n\nclass ExternalWorkItemView(StrictModel):\n    id: UUID\n    organization_id: UUID\n    system_id: UUID\n    risk_id: UUID\n    treatment_id: UUID\n    connector_id: UUID\n    provider: WorkManagementProvider\n    idempotency_key: str\n    title: str\n    status: WorkItemStatus\n    external_id: str | None\n    external_url: str | None\n    payload_sha256: str = Field(pattern=r"^[a-f0-9]{64}$")\n    response_metadata: dict[str, Any]\n    last_error_code: str | None\n    last_error_message: str | None\n    last_synced_at: AwareDatetime | None\n    created_by: str\n    created_at: AwareDatetime\n    updated_at: AwareDatetime\n\n\nclass WorkManagementOverview(StrictModel):\n    treatment: RiskTreatmentView | None\n    work_items: list[ExternalWorkItemView]\n')
write('apps/api/src/traceless_api/integrations/work_management.py', '"""Provider-specific, bounded HTTP contracts for enterprise work-item systems."""\n\nfrom __future__ import annotations\n\nimport base64\nimport json\nfrom dataclasses import dataclass\nfrom typing import Any\nfrom urllib.parse import quote, urlsplit\n\nimport httpx\n\nfrom traceless_api.core.config import WorkManagementCredentialBinding\nfrom traceless_api.db.models import RiskRow\nfrom traceless_api.db.work_management import (\n    RiskTreatmentRow,\n    WorkManagementConnectorRow,\n)\n\n\nclass WorkManagementIntegrationError(RuntimeError):\n    def __init__(self, code: str, message: str) -> None:\n        super().__init__(message)\n        self.code = code\n\n\n@dataclass(frozen=True, slots=True)\nclass ProviderRequest:\n    method: str\n    url: str\n    headers: dict[str, str]\n    payload: Any\n\n\n@dataclass(frozen=True, slots=True)\nclass ProviderResult:\n    external_id: str\n    external_url: str | None\n    status: str\n    metadata: dict[str, Any]\n\n\ndef canonical_origin(value: str) -> str:\n    parsed = urlsplit(value)\n    host = parsed.hostname.rstrip(".").casefold() if parsed.hostname else ""\n    rendered_host = f"[{host}]" if ":" in host else host\n    rendered_port = f":{parsed.port}" if parsed.port not in {None, 443} else ""\n    return f"https://{rendered_host}{rendered_port}"\n\n\ndef _auth_headers(binding: WorkManagementCredentialBinding) -> dict[str, str]:\n    secret = binding.secret.get_secret_value()\n    if binding.auth_scheme == "Bearer":\n        return {"Authorization": f"Bearer {secret}"}\n    if binding.auth_scheme == "Basic":\n        username = binding.username or ""\n        encoded = base64.b64encode(f"{username}:{secret}".encode()).decode()\n        return {"Authorization": f"Basic {encoded}"}\n    if binding.auth_scheme == "PAT":\n        encoded = base64.b64encode(f":{secret}".encode()).decode()\n        return {"Authorization": f"Basic {encoded}"}\n    header_name = binding.header_name or "X-API-Key"\n    return {header_name: secret}\n\n\ndef _risk_description(\n    risk: RiskRow,\n    treatment: RiskTreatmentRow,\n    *,\n    explicit: str | None,\n) -> str:\n    if explicit:\n        return explicit\n    controls = "\\n".join(f"- {item}" for item in treatment.compensating_controls)\n    sections = [\n        f"Traceless risk: {risk.title}",\n        f"Risk level: {risk.level} ({risk.score}/25)",\n        f"Likelihood / impact: {risk.likelihood}/5 / {risk.impact}/5",\n        f"Treatment: {treatment.strategy} / {treatment.status}",\n        f"Owner: {treatment.owner}",\n        f"Due: {treatment.due_at.isoformat() if treatment.due_at else \'not set\'}",\n        f"Rationale: {treatment.rationale or \'not documented\'}",\n    ]\n    if controls:\n        sections.extend(["Compensating controls:", controls])\n    return "\\n\\n".join(sections)\n\n\ndef build_create_request(\n    connector: WorkManagementConnectorRow,\n    risk: RiskRow,\n    treatment: RiskTreatmentRow,\n    *,\n    title: str | None,\n    description: str | None,\n    binding: WorkManagementCredentialBinding,\n) -> ProviderRequest:\n    if canonical_origin(connector.base_url) != binding.origin:\n        raise WorkManagementIntegrationError(\n            "credential_origin_mismatch",\n            "The credential binding is not pinned to the connector origin",\n        )\n    headers = {"Accept": "application/json", **_auth_headers(binding)}\n    summary = title or f"[Traceless {risk.level.upper()}] {risk.title}"\n    body = _risk_description(risk, treatment, explicit=description)\n    base = connector.base_url.rstrip("/")\n\n    if connector.provider == "jira":\n        issue_type = str(connector.settings.get("issue_type") or "Task")\n        payload = {\n            "fields": {\n                "project": {"key": connector.project_key},\n                "issuetype": {"name": issue_type},\n                "summary": summary,\n                "description": {\n                    "type": "doc",\n                    "version": 1,\n                    "content": [\n                        {\n                            "type": "paragraph",\n                            "content": [{"type": "text", "text": body}],\n                        }\n                    ],\n                },\n                "labels": ["traceless", f"risk-{risk.level}"],\n            }\n        }\n        headers["Content-Type"] = "application/json"\n        return ProviderRequest("POST", f"{base}/rest/api/3/issue", headers, payload)\n\n    if connector.provider == "servicenow":\n        table = str(connector.settings.get("table") or "task")\n        if not table.replace("_", "").isalnum():\n            raise WorkManagementIntegrationError(\n                "invalid_servicenow_table",\n                "ServiceNow table names must be alphanumeric or underscores",\n            )\n        impact = {"critical": "1", "high": "1", "medium": "2", "low": "3"}[risk.level]\n        urgency = {"critical": "1", "high": "2", "medium": "2", "low": "3"}[risk.level]\n        payload = {\n            "short_description": summary,\n            "description": body,\n            "impact": impact,\n            "urgency": urgency,\n            "correlation_id": f"traceless-risk-{risk.id}",\n        }\n        if assignment_group := connector.settings.get("assignment_group"):\n            payload["assignment_group"] = str(assignment_group)\n        headers["Content-Type"] = "application/json"\n        return ProviderRequest(\n            "POST",\n            f"{base}/api/now/table/{quote(table, safe=\'\')}",\n            headers,\n            payload,\n        )\n\n    work_item_type = str(connector.settings.get("work_item_type") or "Issue")\n    project = quote(connector.project_key, safe="")\n    item_type = quote(work_item_type, safe="")\n    payload = [\n        {"op": "add", "path": "/fields/System.Title", "value": summary},\n        {\n            "op": "add",\n            "path": "/fields/System.Description",\n            "value": body.replace("\\n", "<br/>"),\n        },\n        {"op": "add", "path": "/fields/System.Tags", "value": f"Traceless; Risk-{risk.level}"},\n    ]\n    headers["Content-Type"] = "application/json-patch+json"\n    return ProviderRequest(\n        "POST",\n        f"{base}/{project}/_apis/wit/workitems/${item_type}?api-version=7.1",\n        headers,\n        payload,\n    )\n\n\ndef build_sync_request(\n    connector: WorkManagementConnectorRow,\n    *,\n    external_id: str,\n    binding: WorkManagementCredentialBinding,\n) -> ProviderRequest:\n    if canonical_origin(connector.base_url) != binding.origin:\n        raise WorkManagementIntegrationError(\n            "credential_origin_mismatch",\n            "The credential binding is not pinned to the connector origin",\n        )\n    headers = {"Accept": "application/json", **_auth_headers(binding)}\n    base = connector.base_url.rstrip("/")\n    if connector.provider == "jira":\n        return ProviderRequest(\n            "GET",\n            f"{base}/rest/api/3/issue/{quote(external_id, safe=\'\')}?fields=status,resolution,updated",\n            headers,\n            None,\n        )\n    if connector.provider == "servicenow":\n        table = str(connector.settings.get("table") or "task")\n        return ProviderRequest(\n            "GET",\n            f"{base}/api/now/table/{quote(table, safe=\'\')}/{quote(external_id, safe=\'\')}"\n            "?sysparm_fields=sys_id,number,state,active,sys_updated_on",\n            headers,\n            None,\n        )\n    project = quote(connector.project_key, safe="")\n    return ProviderRequest(\n        "GET",\n        f"{base}/{project}/_apis/wit/workitems/{quote(external_id, safe=\'\')}"\n        "?api-version=7.1",\n        headers,\n        None,\n    )\n\n\ndef _safe_external_url(\n    connector: WorkManagementConnectorRow,\n    candidate: Any,\n) -> str | None:\n    if not isinstance(candidate, str) or not candidate:\n        return None\n    parsed = urlsplit(candidate)\n    try:\n        matches_origin = canonical_origin(candidate) == canonical_origin(connector.base_url)\n    except ValueError:\n        return None\n    if parsed.scheme.casefold() != "https" or not matches_origin:\n        return None\n    return candidate\n\n\ndef parse_create_result(\n    connector: WorkManagementConnectorRow,\n    payload: dict[str, Any],\n) -> ProviderResult:\n    if connector.provider == "jira":\n        external_id = str(payload.get("key") or payload.get("id") or "")\n        url = f"{connector.base_url.rstrip(\'/\')}/browse/{external_id}" if external_id else None\n        status = "open"\n    elif connector.provider == "servicenow":\n        result = payload.get("result")\n        if not isinstance(result, dict):\n            result = {}\n        external_id = str(result.get("sys_id") or result.get("number") or "")\n        url = _safe_external_url(connector, result.get("link"))\n        status = _normalize_status(str(result.get("state") or "open"))\n        payload = result\n    else:\n        external_id = str(payload.get("id") or "")\n        links = payload.get("_links")\n        html = links.get("html") if isinstance(links, dict) else None\n        url = _safe_external_url(\n            connector,\n            html.get("href") if isinstance(html, dict) else None,\n        )\n        fields = payload.get("fields")\n        status = _normalize_status(\n            str(fields.get("System.State") if isinstance(fields, dict) else "open")\n        )\n    if not external_id:\n        raise WorkManagementIntegrationError(\n            "invalid_provider_response",\n            "The provider response did not include a work-item identifier",\n        )\n    return ProviderResult(external_id, url, status, _safe_metadata(payload))\n\n\ndef parse_sync_result(\n    connector: WorkManagementConnectorRow,\n    payload: dict[str, Any],\n    *,\n    external_id: str,\n) -> ProviderResult:\n    if connector.provider == "jira":\n        fields = payload.get("fields")\n        status_obj = fields.get("status") if isinstance(fields, dict) else None\n        provider_status = (\n            status_obj.get("name") if isinstance(status_obj, dict) else "open"\n        )\n        url = f"{connector.base_url.rstrip(\'/\')}/browse/{external_id}"\n    elif connector.provider == "servicenow":\n        result = payload.get("result")\n        if not isinstance(result, dict):\n            result = {}\n        provider_status = str(result.get("state") or ("open" if result.get("active") else "closed"))\n        url = _safe_external_url(connector, result.get("link"))\n        payload = result\n    else:\n        fields = payload.get("fields")\n        provider_status = (\n            str(fields.get("System.State") or "open")\n            if isinstance(fields, dict)\n            else "open"\n        )\n        links = payload.get("_links")\n        html = links.get("html") if isinstance(links, dict) else None\n        url = _safe_external_url(\n            connector,\n            html.get("href") if isinstance(html, dict) else None,\n        )\n    return ProviderResult(\n        external_id,\n        url,\n        _normalize_status(str(provider_status)),\n        _safe_metadata(payload),\n    )\n\n\ndef _normalize_status(value: str) -> str:\n    normalized = value.strip().casefold().replace(" ", "_")\n    if normalized in {"done", "resolved", "resolution", "fixed"}:\n        return "resolved"\n    if normalized in {"closed", "cancelled", "canceled", "removed"}:\n        return "closed"\n    if normalized in {"in_progress", "active", "implementing", "started"}:\n        return "in_progress"\n    if normalized in {"failed", "error"}:\n        return "failed"\n    return "open"\n\n\ndef _safe_metadata(payload: dict[str, Any]) -> dict[str, Any]:\n    encoded = json.dumps(payload, default=str, separators=(",", ":"))\n    if len(encoded) <= 32_000:\n        return payload\n    return {"truncated": True, "response_bytes": len(encoded.encode())}\n\n\nasync def send_provider_request(\n    request: ProviderRequest,\n    *,\n    timeout_seconds: float,\n    max_response_bytes: int,\n) -> dict[str, Any]:\n    try:\n        async with httpx.AsyncClient(\n            timeout=timeout_seconds,\n            follow_redirects=False,\n            trust_env=False,\n        ) as client:\n            request_kwargs: dict[str, Any] = {"headers": request.headers}\n            if request.payload is not None:\n                request_kwargs["json"] = request.payload\n            async with client.stream(\n                request.method,\n                request.url,\n                **request_kwargs,\n            ) as response:\n                if 300 <= response.status_code < 400:\n                    raise WorkManagementIntegrationError(\n                        "provider_redirect_rejected",\n                        "Provider redirects are not followed",\n                    )\n                chunks: list[bytes] = []\n                size = 0\n                async for chunk in response.aiter_bytes():\n                    size += len(chunk)\n                    if size > max_response_bytes:\n                        raise WorkManagementIntegrationError(\n                            "provider_response_too_large",\n                            "Provider response exceeded the configured size limit",\n                        )\n                    chunks.append(chunk)\n                body = b"".join(chunks)\n                content_type = response.headers.get("Content-Type", "")\n                if body and "json" not in content_type.casefold():\n                    raise WorkManagementIntegrationError(\n                        "invalid_provider_content_type",\n                        "The provider response is not JSON",\n                    )\n                if response.status_code >= 400:\n                    raise WorkManagementIntegrationError(\n                        f"provider_http_{response.status_code}",\n                        f"Provider request failed with HTTP {response.status_code}",\n                    )\n    except httpx.HTTPError as error:\n        raise WorkManagementIntegrationError(\n            "provider_transport_error",\n            "The provider could not be reached",\n        ) from error\n    if not body:\n        return {}\n    try:\n        parsed = json.loads(body)\n    except json.JSONDecodeError as error:\n        raise WorkManagementIntegrationError(\n            "invalid_provider_json",\n            "The provider returned invalid JSON",\n        ) from error\n    if not isinstance(parsed, dict):\n        raise WorkManagementIntegrationError(\n            "invalid_provider_response",\n            "The provider response must be a JSON object",\n        )\n    return parsed\n')
write('apps/api/src/traceless_api/services/work_management.py', '"""Risk-treatment lifecycle and enterprise ticket orchestration."""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nfrom datetime import UTC, datetime\nfrom uuid import UUID\n\nfrom sqlalchemy import select\n\nfrom traceless_api.core.config import Settings, WorkManagementCredentialBinding\nfrom traceless_api.db.models import RiskRow\nfrom traceless_api.db.work_management import (\n    ExternalWorkItemRow,\n    RiskTreatmentRow,\n    WorkManagementConnectorRow,\n)\nfrom traceless_api.integrations.work_management import (\n    WorkManagementIntegrationError,\n    build_create_request,\n    build_sync_request,\n    parse_create_result,\n    parse_sync_result,\n    send_provider_request,\n)\nfrom traceless_api.models.work_management import (\n    ExternalWorkItemCreate,\n    RiskTreatmentUpsert,\n    WorkManagementConnectorCreate,\n    WorkManagementConnectorUpdate,\n)\nfrom traceless_api.services.operational_repository import (\n    OperationalConflictError,\n    OperationalNotFoundError,\n    OperationalRepository,\n)\n\n\nclass WorkManagementService:\n    def __init__(self, repository: OperationalRepository, settings: Settings) -> None:\n        self.repository = repository\n        self.session = repository.session\n        self.settings = settings\n\n    def list_connectors(self) -> list[WorkManagementConnectorRow]:\n        if self.repository.organization_id is None:\n            raise OperationalConflictError("Connector listing requires an organization boundary")\n        return list(\n            self.session.scalars(\n                select(WorkManagementConnectorRow)\n                .where(\n                    WorkManagementConnectorRow.organization_id\n                    == self.repository.organization_id\n                )\n                .order_by(WorkManagementConnectorRow.name)\n            )\n        )\n\n    def create_connector(\n        self,\n        payload: WorkManagementConnectorCreate,\n        *,\n        actor: str,\n    ) -> WorkManagementConnectorRow:\n        if self.repository.organization_id is None:\n            raise OperationalConflictError("Connector creation requires an organization boundary")\n        existing = self.session.scalar(\n            select(WorkManagementConnectorRow).where(\n                WorkManagementConnectorRow.organization_id\n                == self.repository.organization_id,\n                WorkManagementConnectorRow.name == payload.name,\n            )\n        )\n        if existing is not None:\n            raise OperationalConflictError("A connector with that name already exists")\n        row = WorkManagementConnectorRow(\n            organization_id=self.repository.organization_id,\n            created_by=actor,\n            updated_by=actor,\n            **payload.model_dump(),\n        )\n        self.session.add(row)\n        self.session.flush()\n        self.repository.audit(\n            actor,\n            "work_management.connector_created",\n            "work_management_connector",\n            row.id,\n            {"provider": row.provider, "name": row.name},\n        )\n        return row\n\n    def update_connector(\n        self,\n        connector_id: UUID,\n        payload: WorkManagementConnectorUpdate,\n        *,\n        actor: str,\n    ) -> WorkManagementConnectorRow:\n        row = self._get_connector(connector_id)\n        duplicate = self.session.scalar(\n            select(WorkManagementConnectorRow.id).where(\n                WorkManagementConnectorRow.organization_id == row.organization_id,\n                WorkManagementConnectorRow.name == payload.name,\n                WorkManagementConnectorRow.id != row.id,\n            )\n        )\n        if duplicate is not None:\n            raise OperationalConflictError("A connector with that name already exists")\n        for key, value in payload.model_dump().items():\n            setattr(row, key, value)\n        row.updated_by = actor\n        self.session.flush()\n        self.repository.audit(\n            actor,\n            "work_management.connector_updated",\n            "work_management_connector",\n            row.id,\n            {"provider": row.provider, "enabled": row.enabled},\n        )\n        return row\n\n    def get_treatment(self, system_id: UUID, risk_id: UUID) -> RiskTreatmentRow | None:\n        self._get_risk(system_id, risk_id)\n        return self.session.scalar(\n            select(RiskTreatmentRow).where(\n                RiskTreatmentRow.system_id == system_id,\n                RiskTreatmentRow.risk_id == risk_id,\n            )\n        )\n\n    def upsert_treatment(\n        self,\n        system_id: UUID,\n        risk_id: UUID,\n        payload: RiskTreatmentUpsert,\n        *,\n        actor: str,\n    ) -> RiskTreatmentRow:\n        risk = self._get_risk(system_id, risk_id)\n        if self.repository.organization_id is None:\n            raise OperationalConflictError("Risk treatment requires an organization boundary")\n        row = self.session.scalar(\n            select(RiskTreatmentRow)\n            .where(\n                RiskTreatmentRow.system_id == system_id,\n                RiskTreatmentRow.risk_id == risk_id,\n            )\n            .with_for_update()\n        )\n        values = payload.model_dump(exclude={"expected_version"})\n        if row is None:\n            if payload.expected_version is not None:\n                raise OperationalConflictError("Risk treatment does not yet exist")\n            row = RiskTreatmentRow(\n                organization_id=self.repository.organization_id,\n                system_id=system_id,\n                risk_id=risk.id,\n                created_by=actor,\n                updated_by=actor,\n                version=1,\n                **values,\n            )\n            self.session.add(row)\n            action = "work_management.treatment_created"\n        else:\n            if payload.expected_version is not None and row.version != payload.expected_version:\n                raise OperationalConflictError(\n                    "Risk treatment changed since it was loaded; refresh and try again"\n                )\n            for key, value in values.items():\n                setattr(row, key, value)\n            row.updated_by = actor\n            row.version += 1\n            action = "work_management.treatment_updated"\n        self.session.flush()\n        self.repository.audit(\n            actor,\n            action,\n            "risk_treatment",\n            row.id,\n            {\n                "risk_id": str(risk.id),\n                "strategy": row.strategy,\n                "status": row.status,\n                "owner": row.owner,\n                "version": row.version,\n            },\n        )\n        return row\n\n    def list_work_items(\n        self,\n        system_id: UUID,\n        *,\n        risk_id: UUID | None = None,\n    ) -> list[ExternalWorkItemRow]:\n        self.repository.get_system(system_id)\n        statement = select(ExternalWorkItemRow).where(\n            ExternalWorkItemRow.system_id == system_id\n        )\n        if risk_id is not None:\n            self._get_risk(system_id, risk_id)\n            statement = statement.where(ExternalWorkItemRow.risk_id == risk_id)\n        return list(\n            self.session.scalars(\n                statement.order_by(ExternalWorkItemRow.created_at.desc())\n            )\n        )\n\n    async def create_work_item(\n        self,\n        system_id: UUID,\n        risk_id: UUID,\n        payload: ExternalWorkItemCreate,\n        *,\n        actor: str,\n    ) -> ExternalWorkItemRow:\n        risk = self._get_risk(system_id, risk_id)\n        treatment = self.get_treatment(system_id, risk_id)\n        if treatment is None:\n            raise OperationalConflictError(\n                "Create and assign a risk treatment before creating an external work item"\n            )\n        connector = self._get_connector(payload.connector_id)\n        if not connector.enabled:\n            raise OperationalConflictError("The selected connector is disabled")\n        if self.repository.organization_id is None:\n            raise OperationalConflictError("Work-item creation requires an organization boundary")\n\n        existing = self.session.scalar(\n            select(ExternalWorkItemRow).where(\n                ExternalWorkItemRow.organization_id == self.repository.organization_id,\n                (\n                    (ExternalWorkItemRow.idempotency_key == payload.idempotency_key)\n                    | (\n                        (ExternalWorkItemRow.risk_id == risk_id)\n                        & (ExternalWorkItemRow.connector_id == connector.id)\n                    )\n                ),\n            )\n        )\n        if existing is not None and (\n            existing.risk_id != risk_id or existing.connector_id != connector.id\n        ):\n            raise OperationalConflictError(\n                "The idempotency key belongs to another risk or connector"\n            )\n        if existing is not None and existing.status != "failed":\n            return existing\n\n        try:\n            request = build_create_request(\n                connector,\n                risk,\n                treatment,\n                title=payload.title,\n                description=payload.description,\n                binding=self._credential(connector),\n            )\n        except WorkManagementIntegrationError as error:\n            raise OperationalConflictError(str(error)) from error\n        request_payload = {\n            "method": request.method,\n            "url": request.url,\n            "headers": sorted(\n                key for key in request.headers if key.casefold() != "authorization"\n            ),\n            "payload": request.payload,\n        }\n        digest = hashlib.sha256(\n            json.dumps(request_payload, sort_keys=True, default=str).encode()\n        ).hexdigest()\n        if existing is None:\n            row = ExternalWorkItemRow(\n                organization_id=self.repository.organization_id,\n                system_id=system_id,\n                risk_id=risk_id,\n                treatment_id=treatment.id,\n                connector_id=connector.id,\n                provider=connector.provider,\n                idempotency_key=payload.idempotency_key,\n                title=payload.title or f"[Traceless {risk.level.upper()}] {risk.title}",\n                status="pending",\n                payload_sha256=digest,\n                request_payload=request_payload,\n                created_by=actor,\n            )\n            self.session.add(row)\n        else:\n            row = existing\n            row.status = "pending"\n            row.payload_sha256 = digest\n            row.request_payload = request_payload\n            row.last_error_code = None\n            row.last_error_message = None\n        self.session.flush()\n\n        try:\n            response = await send_provider_request(\n                request,\n                timeout_seconds=self.settings.work_management_timeout_seconds,\n                max_response_bytes=self.settings.work_management_max_response_bytes,\n            )\n            result = parse_create_result(connector, response)\n        except WorkManagementIntegrationError as error:\n            row.status = "failed"\n            row.last_error_code = error.code\n            row.last_error_message = str(error)\n            row.last_synced_at = datetime.now(UTC)\n        else:\n            row.status = result.status\n            row.external_id = result.external_id\n            row.external_url = result.external_url\n            row.response_metadata = result.metadata\n            row.last_error_code = None\n            row.last_error_message = None\n            row.last_synced_at = datetime.now(UTC)\n        self.session.flush()\n        self.repository.audit(\n            actor,\n            "work_management.work_item_dispatched",\n            "external_work_item",\n            row.id,\n            {\n                "risk_id": str(risk_id),\n                "connector_id": str(connector.id),\n                "provider": connector.provider,\n                "status": row.status,\n                "external_id": row.external_id,\n            },\n        )\n        return row\n\n    async def sync_work_item(\n        self,\n        system_id: UUID,\n        work_item_id: UUID,\n        *,\n        actor: str,\n    ) -> ExternalWorkItemRow:\n        row = self._get_work_item(system_id, work_item_id)\n        if row.external_id is None:\n            raise OperationalConflictError(\n                "The external work item has no provider identifier to synchronize"\n            )\n        connector = self._get_connector(row.connector_id)\n        if not connector.enabled:\n            raise OperationalConflictError("The selected connector is disabled")\n        try:\n            request = build_sync_request(\n                connector,\n                external_id=row.external_id,\n                binding=self._credential(connector),\n            )\n        except WorkManagementIntegrationError as error:\n            raise OperationalConflictError(str(error)) from error\n        try:\n            response = await send_provider_request(\n                request,\n                timeout_seconds=self.settings.work_management_timeout_seconds,\n                max_response_bytes=self.settings.work_management_max_response_bytes,\n            )\n            result = parse_sync_result(\n                connector,\n                response,\n                external_id=row.external_id,\n            )\n        except WorkManagementIntegrationError as error:\n            row.last_error_code = error.code\n            row.last_error_message = str(error)\n            row.last_synced_at = datetime.now(UTC)\n        else:\n            row.status = result.status\n            row.external_url = result.external_url or row.external_url\n            row.response_metadata = result.metadata\n            row.last_error_code = None\n            row.last_error_message = None\n            row.last_synced_at = datetime.now(UTC)\n            treatment = self.session.get(RiskTreatmentRow, row.treatment_id)\n            if treatment is not None and row.status in {"resolved", "closed"}:\n                treatment.status = "completed"\n                treatment.updated_by = actor\n                treatment.version += 1\n        self.session.flush()\n        self.repository.audit(\n            actor,\n            "work_management.work_item_synced",\n            "external_work_item",\n            row.id,\n            {"status": row.status, "external_id": row.external_id},\n        )\n        return row\n\n    def _get_risk(self, system_id: UUID, risk_id: UUID) -> RiskRow:\n        self.repository.get_system(system_id)\n        row = self.session.scalar(\n            select(RiskRow).where(\n                RiskRow.id == risk_id,\n                RiskRow.system_id == system_id,\n            )\n        )\n        if row is None:\n            raise OperationalNotFoundError("Risk was not found")\n        return row\n\n    def _get_connector(self, connector_id: UUID) -> WorkManagementConnectorRow:\n        statement = select(WorkManagementConnectorRow).where(\n            WorkManagementConnectorRow.id == connector_id\n        )\n        if self.repository.organization_id is not None:\n            statement = statement.where(\n                WorkManagementConnectorRow.organization_id\n                == self.repository.organization_id\n            )\n        row = self.session.scalar(statement)\n        if row is None:\n            raise OperationalNotFoundError("Work-management connector was not found")\n        return row\n\n    def _get_work_item(\n        self,\n        system_id: UUID,\n        work_item_id: UUID,\n    ) -> ExternalWorkItemRow:\n        self.repository.get_system(system_id)\n        row = self.session.scalar(\n            select(ExternalWorkItemRow).where(\n                ExternalWorkItemRow.id == work_item_id,\n                ExternalWorkItemRow.system_id == system_id,\n            )\n        )\n        if row is None:\n            raise OperationalNotFoundError("External work item was not found")\n        return row\n\n    def _credential(\n        self,\n        connector: WorkManagementConnectorRow,\n    ) -> WorkManagementCredentialBinding:\n        organization_key = self.repository.organization_key\n        if not organization_key:\n            raise OperationalConflictError("Credential resolution requires an organization key")\n        binding = self.settings.work_management_credentials.get(\n            organization_key,\n            {},\n        ).get(connector.credential_reference)\n        if binding is None:\n            raise OperationalConflictError(\n                "The configured credential reference is unavailable to this tenant"\n            )\n        return binding\n')
write('apps/api/src/traceless_api/api/routes/work_management.py', '"""Enterprise risk-treatment and external work-item routes."""\n\nfrom __future__ import annotations\n\nfrom typing import Annotated\nfrom uuid import UUID\n\nfrom fastapi import APIRouter, Depends, Query, Request, status\n\nfrom traceless_api.api.auth import (\n    OperationalActor,\n    require_analyst_access,\n    require_org_wide_admin_access,\n    require_read_access,\n)\nfrom traceless_api.api.dependencies import OperationalRepositoryDependency\nfrom traceless_api.models.work_management import (\n    ExternalWorkItemCreate,\n    ExternalWorkItemView,\n    RiskTreatmentUpsert,\n    RiskTreatmentView,\n    WorkManagementConnectorCreate,\n    WorkManagementConnectorUpdate,\n    WorkManagementConnectorView,\n    WorkManagementOverview,\n)\nfrom traceless_api.services.work_management import WorkManagementService\n\nrouter = APIRouter(prefix="/operational", tags=["work-management"])\n\n\n@router.get(\n    "/work-management/connectors",\n    response_model=list[WorkManagementConnectorView],\n    dependencies=[Depends(require_analyst_access)],\n)\ndef list_connectors(\n    request: Request,\n    repository: OperationalRepositoryDependency,\n) -> list[WorkManagementConnectorView]:\n    service = WorkManagementService(repository, request.app.state.settings)\n    return [\n        WorkManagementConnectorView.model_validate(row)\n        for row in service.list_connectors()\n    ]\n\n\n@router.post(\n    "/work-management/connectors",\n    response_model=WorkManagementConnectorView,\n    status_code=status.HTTP_201_CREATED,\n    dependencies=[Depends(require_org_wide_admin_access)],\n)\ndef create_connector(\n    payload: WorkManagementConnectorCreate,\n    request: Request,\n    repository: OperationalRepositoryDependency,\n    actor: OperationalActor,\n) -> WorkManagementConnectorView:\n    service = WorkManagementService(repository, request.app.state.settings)\n    return WorkManagementConnectorView.model_validate(\n        service.create_connector(payload, actor=actor)\n    )\n\n\n@router.put(\n    "/work-management/connectors/{connector_id}",\n    response_model=WorkManagementConnectorView,\n    dependencies=[Depends(require_org_wide_admin_access)],\n)\ndef update_connector(\n    connector_id: UUID,\n    payload: WorkManagementConnectorUpdate,\n    request: Request,\n    repository: OperationalRepositoryDependency,\n    actor: OperationalActor,\n) -> WorkManagementConnectorView:\n    service = WorkManagementService(repository, request.app.state.settings)\n    return WorkManagementConnectorView.model_validate(\n        service.update_connector(connector_id, payload, actor=actor)\n    )\n\n\n@router.get(\n    "/systems/{system_id}/risks/{risk_id}/work-management",\n    response_model=WorkManagementOverview,\n    dependencies=[Depends(require_read_access)],\n)\ndef work_management_overview(\n    system_id: UUID,\n    risk_id: UUID,\n    request: Request,\n    repository: OperationalRepositoryDependency,\n) -> WorkManagementOverview:\n    service = WorkManagementService(repository, request.app.state.settings)\n    treatment = service.get_treatment(system_id, risk_id)\n    return WorkManagementOverview(\n        treatment=(\n            RiskTreatmentView.model_validate(treatment)\n            if treatment is not None\n            else None\n        ),\n        work_items=[\n            ExternalWorkItemView.model_validate(row)\n            for row in service.list_work_items(system_id, risk_id=risk_id)\n        ],\n    )\n\n\n@router.put(\n    "/systems/{system_id}/risks/{risk_id}/treatment",\n    response_model=RiskTreatmentView,\n    dependencies=[Depends(require_analyst_access)],\n)\ndef upsert_treatment(\n    system_id: UUID,\n    risk_id: UUID,\n    payload: RiskTreatmentUpsert,\n    request: Request,\n    repository: OperationalRepositoryDependency,\n    actor: OperationalActor,\n) -> RiskTreatmentView:\n    service = WorkManagementService(repository, request.app.state.settings)\n    return RiskTreatmentView.model_validate(\n        service.upsert_treatment(\n            system_id,\n            risk_id,\n            payload,\n            actor=actor,\n        )\n    )\n\n\n@router.get(\n    "/systems/{system_id}/work-items",\n    response_model=list[ExternalWorkItemView],\n    dependencies=[Depends(require_read_access)],\n)\ndef list_work_items(\n    system_id: UUID,\n    request: Request,\n    repository: OperationalRepositoryDependency,\n    risk_id: Annotated[UUID | None, Query()] = None,\n) -> list[ExternalWorkItemView]:\n    service = WorkManagementService(repository, request.app.state.settings)\n    return [\n        ExternalWorkItemView.model_validate(row)\n        for row in service.list_work_items(system_id, risk_id=risk_id)\n    ]\n\n\n@router.post(\n    "/systems/{system_id}/risks/{risk_id}/work-items",\n    response_model=ExternalWorkItemView,\n    status_code=status.HTTP_201_CREATED,\n    dependencies=[Depends(require_analyst_access)],\n)\nasync def create_work_item(\n    system_id: UUID,\n    risk_id: UUID,\n    payload: ExternalWorkItemCreate,\n    request: Request,\n    repository: OperationalRepositoryDependency,\n    actor: OperationalActor,\n) -> ExternalWorkItemView:\n    service = WorkManagementService(repository, request.app.state.settings)\n    return ExternalWorkItemView.model_validate(\n        await service.create_work_item(\n            system_id,\n            risk_id,\n            payload,\n            actor=actor,\n        )\n    )\n\n\n@router.post(\n    "/systems/{system_id}/work-items/{work_item_id}/sync",\n    response_model=ExternalWorkItemView,\n    dependencies=[Depends(require_analyst_access)],\n)\nasync def sync_work_item(\n    system_id: UUID,\n    work_item_id: UUID,\n    request: Request,\n    repository: OperationalRepositoryDependency,\n    actor: OperationalActor,\n) -> ExternalWorkItemView:\n    service = WorkManagementService(repository, request.app.state.settings)\n    return ExternalWorkItemView.model_validate(\n        await service.sync_work_item(\n            system_id,\n            work_item_id,\n            actor=actor,\n        )\n    )\n')
